package com.autoops.command.retrieval;import com.autoops.command.entity.CommandDefinition;import com.autoops.command.repository.CommandDefinitionRepository;import com.autoops.embedding.EmbeddingService;import org.springframework.stereotype.Service;import java.util.*;@Service public class CommandRetrievalService{private final CommandDefinitionRepository repo;private final EmbeddingService embeddings;public CommandRetrievalService(CommandDefinitionRepository r,EmbeddingService e){repo=r;embeddings=e;}public Result search(String query){var candidates=repo.semantic(embeddings.vector(query),20);var scored=candidates.stream().map(c->new Scored(c,rerank(c,query))).sorted(Comparator.comparingDouble(Scored::score).reversed()).limit(5).toList();if(scored.isEmpty())return new Result("NO_CONFIDENT_MATCH",List.of());if(scored.size()>1&&scored.get(0).score()-scored.get(1).score()<.10)return new Result("AMBIGUOUS",scored);return new Result(scored.get(0).score()>=.45?"MATCH":"NO_CONFIDENT_MATCH",scored);}private double rerank(CommandDefinition c,String q){String text=(c.getName()+" "+c.getDescription()+" "+c.getCategory()+" "+c.getAction()+" "+c.getResourceType()).toLowerCase(Locale.ROOT);long hits=Arrays.stream(q.toLowerCase(Locale.ROOT).split("\\s+")).filter(w->w.length()>2&&text.contains(w)).count();return Math.min(1,.55+hits*.12);}public record Scored(CommandDefinition command,double score){}public record Result(String confidence,List<Scored>matches){}}
